<?php require "config/db.php";require_login();$s=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC");$s->execute([$_SESSION["user"]["id"]]);$orders=$s->fetchAll(); ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My orders | Foody Spot</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include "includes/nav.php"; ?><main class="container page"><div class="page-head"><span class="eyebrow">YOUR FOODY SPOT HISTORY</span><h1>My orders<span>.</span></h1></div><?php if(isset($_GET["placed"])): ?><p class="success">Your order has been placed successfully!</p><?php endif; ?><?php if(!$orders): ?><div class="empty-panel"><h2>No orders yet.</h2><a class="btn" href="menu.php">Explore menu</a></div><?php else: foreach($orders as $o): ?><section class="order-card"><div><b>Order #<?= (int)$o["id"] ?></b><p><?= h(date("d M Y, h:i A",strtotime($o["created_at"]))) ?></p><small><?= h($o["address"]) ?></small></div><div class="order-right"><strong>₹<?= number_format($o["total"],2) ?></strong><span class="status"><?= h($o["status"]) ?></span></div></section><?php endforeach; endif; ?></main><?php include "includes/footer.php"; ?></body></html>